package cz.zcu.ast;

import cz.zcu.CustomLangBaseVisitor;
import cz.zcu.CustomLangParser;
import cz.zcu.ast.nodes.*;

import java.util.ArrayList;
import java.util.List;

/********************************************
 * ASTBuilder is a visitor class that traverses the parse tree generated by ANTLR for the custom language and constructs
 * an abstract syntax tree (AST) representation of the program. It extends the CustomLangBaseVisitor class and overrides
 * its visit methods to create specific AST nodes for different constructs in the language.
 *
 * @author Michael Hladky, Victor Verner
 * @version 1.0
 ********************************************/
public class ASTBuilder extends CustomLangBaseVisitor<IAstNode> {

    /**
     * Visits a block of code in the parse tree and constructs a corresponding BlockNode in the abstract syntax tree
     * (AST).
     *
     * @param ctx the context of the block in the parse tree
     * @return a BlockNode representing the block of code
     **/
    @Override
    public IAstNode visitBlock(CustomLangParser.BlockContext ctx) {

        BlockNode blockNode = new BlockNode();

        // Iterate over each statement in the block and visit it to construct the corresponding AST nodes
        for (CustomLangParser.StatementContext statCtx : ctx.statement()) {

            IAstNode statement = visit(statCtx);

            if (statement != null) {
                blockNode.statements.add(statement);
            }
        }

        return blockNode;
    }

    /**
     * Visits a variable declaration in the parse tree and constructs a corresponding VarDeclNode in the abstract syntax
     * tree (AST).
     *
     * @param ctx the context of the variable declaration in the parse tree
     * @return a VarDeclNode representing the variable declaration
     **/
    @Override
    public IAstNode visitVarDecl(CustomLangParser.VarDeclContext ctx) {
        String type = ctx.type().getText();
        String name = ctx.ID().getText();

        IAstNode expression = null;

        if (ctx.expr() != null) {
            expression = visit(ctx.expr());
        }

        return new VarDeclNode(type, name, expression);
    }

    /**
     * Visits a program in the parse tree and constructs a corresponding ProgramNode in the abstract syntax tree (AST).
     *
     * @param ctx the context of the program in the parse tree
     * @return a ProgramNode representing the program
     **/
    @Override
    public IAstNode visitProgram(CustomLangParser.ProgramContext ctx) {
        // gets the name of the program
        String programName = ctx.ID().getText();

        // processes the code block
        IAstNode codeBlock = visit(ctx.codeBlock());

        return new ProgramNode(programName, codeBlock);
    }

    /**
     * Visits a code block in the parse tree and constructs a corresponding AST node by visiting the inner block.
     *
     * @param ctx the context of the code block in the parse tree
     * @return an AST node representing the inner block of code
     **/
    @Override
    public IAstNode visitCodeBlock(CustomLangParser.CodeBlockContext ctx) {
        return visit(ctx.block()); // skip the code word and go straight to the code inside brackets
    }

    /**
     * Visits an identifier statement in the parse tree and constructs a corresponding AST node, which can be either a
     * CallNode for function calls or an AssignNode for variable assignments.
     *
     * @param ctx the context of the identifier statement in the parse tree
     * @return an AST node representing the identifier statement (CallNode or AssignNode)
     **/
    @Override
    public IAstNode visitIdStat(CustomLangParser.IdStatContext ctx) {
        String identifierName = ctx.ID().getText();

        // if followed by (), its calling of subprogram
        if (ctx.callTail() != null) {
            List<IAstNode> arguments = new ArrayList<>();

            // if there are some parameters in ()
            if (ctx.callTail().argList() != null) {
                // go over all parameters separated by , and process them
                for (CustomLangParser.ExprContext exprCtx : ctx.callTail().argList().expr()) {
                    arguments.add(visit(exprCtx));
                }
            }
            return new CallNode(identifierName, arguments);
        }

//        // if followed by := or =, its assignment of variable
//        if (ctx.assignTail() != null) {
//
//            IAstNode expression = visit(ctx.assignTail().expr());
//
//
//            return new AssignNode(identifierName, expression);
//        }

        return null;
    }

    /**
     * Visits a string literal expression in the parse tree and constructs a corresponding StringNode in the abstract
     * syntax tree (AST).
     *
     * @param ctx the context of the string literal expression in the parse tree
     * @return a StringNode representing the string literal
     **/
    @Override
    public IAstNode visitStrLitExpr(CustomLangParser.StrLitExprContext ctx) {
        // get text from parser remove the start end ending brackets just the string inside
        String cleanText = ctx.STRING_LITERAL().getText();
        if (cleanText.startsWith("\"") && cleanText.endsWith("\"") && cleanText.length() >= 2) {
            cleanText = cleanText.substring(1, cleanText.length() - 1);
        }

        return new StringNode(cleanText);
    }

    /**
     * Visits a while statement in the parse tree and constructs a corresponding WhileNode in the abstract syntax tree
     * (AST).
     *
     * @param ctx the context of the while statement in the parse tree
     * @return a WhileNode representing the while loop
     **/
    @Override
    public IAstNode visitWhileStat(CustomLangParser.WhileStatContext ctx) {
        // condition of the while loop
        IAstNode condition = visit(ctx.expr());
        // code in the while loop
        IAstNode body = visit(ctx.block());

        return new WhileNode(condition, body);
    }

    /**
     * Visits an if statement in the parse tree and constructs a corresponding IfElseNode in the abstract syntax tree
     * (AST).
     *
     * @param ctx the context of the if statement in the parse tree
     * @return an IfElseNode representing the if-else statement
     **/
    @Override
    public IAstNode visitIfStat(CustomLangParser.IfStatContext ctx) {
        IAstNode condition = visit(ctx.expr());
        IAstNode thenBlock = visit(ctx.block(0)); // first if block

        IAstNode elseBlock = null;
        if (ctx.block().size() > 1) {
            elseBlock = visit(ctx.block(1)); // else block
        }

        return new IfElseNode(condition, thenBlock, elseBlock);
    }

    /**
     * Visits a call expression in the parse tree and constructs a corresponding AST node, which can be either a
     * CallNode for function calls or variable - IdentificationNode for variable usage.
     *
     * @param ctx the context of the call expression in the parse tree
     * @return an AST node representing the call expression (CallNode or IdentificationNode)
     **/
    @Override
    public IAstNode visitCallExpr(CustomLangParser.CallExprContext ctx) {
        // get the name of the identifier (function or variable)
        String identifierName = ctx.ID().getText();

        // determine if it's a function call or variable usage based on the presence of ()
        if (ctx.LPAREN() == null) {
            // no () it's a variable
            return new IdentificationNode(identifierName);
        }

        // if there are () it's a function call, we need to process the arguments
        List<IAstNode> arguments = new ArrayList<>();

        // check if there are any arguments, go over all parameters separated by ,
        // and process them
        if (ctx.argList() != null) {
            for (CustomLangParser.ExprContext exprCtx : ctx.argList().expr()) {
                arguments.add(visit(exprCtx));
            }
        }

        return new CallNode(identifierName, arguments);
    }

    /**
     * Visits an integer literal expression in the parse tree and constructs a corresponding IntegerNode in the abstract
     * syntax tree (AST).
     *
     * @param ctx the context of the integer literal expression in the parse tree
     * @return an IntegerNode representing the integer literal
     **/
    @Override
    public IAstNode visitIntLitExpr(CustomLangParser.IntLitExprContext ctx) {
        int value = Integer.parseInt(ctx.INT_LITERAL().getText());
        return new IntegerNode(value);
    }

    /**
     * Wraps the visitForStat method to handle the ForStatementContext in the parse tree, for some reason ANTLR
     * generates a ForStatementContext that contains a ForStatContext, so we just delegate the visit to the visitForStat
     * method.
     *
     * @param ctx the context of the for statement in the parse tree
     * @return a ForNode representing the for loop
     **/
    @Override
    public IAstNode visitForStatement(CustomLangParser.ForStatementContext ctx) {
        return visitForStat(ctx.forStat());
    }

    /**
     * Visits a for statement in the parse tree and constructs a corresponding ForNode in the abstract syntax tree
     * (AST).
     *
     * @param ctx the context of the for statement in the parse tree
     * @return a ForNode representing the for loop
     **/
    @Override
    public IAstNode visitForStat(CustomLangParser.ForStatContext ctx) {
        String iteratorName = ctx.forInit().ID().getText();
        IAstNode initExpression = visit(ctx.forInit().expr());
        IAstNode toExpression = visit(ctx.expr());
        IAstNode body = visit(ctx.block());

        return new ForNode(iteratorName, initExpression, toExpression, body);
    }

    /**
     * Visits a real literal expression in the parse tree and constructs a corresponding RealNode in the abstract syntax
     * tree (AST).
     *
     * @param ctx the context of the real literal expression in the parse tree
     * @return a RealNode representing the real literal
     **/
    @Override
    public IAstNode visitRealLitExpr(CustomLangParser.RealLitExprContext ctx) {
        double value = Double.parseDouble(ctx.REAL_LITERAL().getText());
        return new RealNode(value);
    }

    /**
     * Visits a boolean literal expression in the parse tree and constructs a corresponding BooleanNode in the abstract
     * syntax tree (AST).
     *
     * @param ctx the context of the boolean literal expression in the parse tree
     * @return a BooleanNode representing the boolean literal
     **/
    @Override
    public IAstNode visitBoolLitExpr(CustomLangParser.BoolLitExprContext ctx) {
        boolean value = Boolean.parseBoolean(ctx.BOOL_LITERAL().getText());
        return new BooleanNode(value);
    }

    /**
     * Visits a prefix expression in the parse tree and constructs a corresponding OperationNode in the abstract syntax
     * tree (AST). A prefix expression consists of an operator followed by a list of arguments enclosed in parentheses.
     *
     * @param ctx the context of the prefix expression in the parse tree
     * @return an OperationNode representing the prefix expression
     **/
    @Override
    public IAstNode visitPrefixExpr(CustomLangParser.PrefixExprContext ctx) {
        String operator = ctx.prefixOp().getText();

        List<IAstNode> operands = new ArrayList<>();

        // check if there are any arguments in the parentheses
        if (ctx.argList() != null) {
            for (CustomLangParser.ExprContext exprCtx : ctx.argList().expr()) {
                operands.add(visit(exprCtx));
            }
        }

        return new OperationNode(operator, operands);
    }

}